async function one<T>(table:string){return(await db.list<T>(table,{limit:1})).items[0]}
async function upsertOne(table:string,record:Record<string,unknown>){const row=await one<Record<string,unknown>>(table);if(row){const[ok]=await db.update(table,[{id:row.id,record}]);if(!ok)throw new Error(table+'_update_failed')}else{const[id]=await db.add(table,[record]);if(!id)throw new Error(table+'_insert_failed')}}
async function audit(actor:string,action:string,target='',detail:unknown=null){await db.add('audit_logs_v2',[{actor:norm(actor),action,target,detail,createdAt:Date.now()}])}
async function members(){return(await db.list<Member>('admin_members',{limit:100})).items}
async function roleFor(email?:string):Promise<Role|null>{const e=norm(email);if(e===norm(ROOT))return'owner';const m=(await members()).find(x=>norm(x.email)===e&&x.active);return m?.role||null}
const requireManager=()=>async(ctx:{user?:{email?:string}})=>{if(!await roleFor(ctx.user?.email))return error('forbidden',403)};
