async function postToFacebook(a:Article){const c=await getFacebookConfig();if(!c.enabled||!c.pageId||!c.pageAccessToken)return{configured:false,posted:false};const[h]=await hydrate([a]),pub=cleanPublic(h as Article),image=originalSourceImage(pub.imageUrl)||pub.imageUrl||FALLBACK_IMAGE,articleUrl=ORIGIN+'/share/'+encodeURIComponent(a.id||''),message=[pub.title,pub.body,articleUrl].filter(Boolean).join('\n\n'),form=new URLSearchParams();form.set('access_token',c.pageAccessToken);form.set('url',image);form.set('caption',message);form.set('published','true');try{const r=await fetch('https://graph.facebook.com/'+encodeURIComponent(c.pageId)+'/photos',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:form.toString()}),data=await r.json().catch(()=>({}));if(!r.ok)return{configured:true,posted:false,error:String((data as{error?:{message?:string}}).error?.message||'facebook_error')};return{configured:true,posted:true,id:String((data as{post_id?:string;id?:string}).post_id||(data as{id?:string}).id||'')}}catch(e){return{configured:true,posted:false,error:e instanceof Error?e.message:'facebook_error'}}}
function xml(v:unknown){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
async function facebookRss(){const items=await publicArticles(),parts=items.slice(0,50).map(a=>{if(!a.id||!a.imageUrl)return'';const u=ORIGIN+'/share/'+encodeURIComponent(a.id),desc=[a.title,a.body,u].filter(Boolean).map(xml).join('&#10;&#10;');return'<item><title>'+xml(a.title)+'</title><link>'+xml(u)+'</link><guid isPermaLink="true">'+xml(u)+'</guid><pubDate>'+new Date(a.published_at||a.created_at).toUTCString()+'</pubDate><category>'+xml(a.category)+'</category><description>'+desc+'</description><enclosure url="'+xml(a.imageUrl)+'" type="image/jpeg"/><media:content url="'+xml(a.imageUrl)+'" medium="image" type="image/jpeg"/></item>'}).filter(Boolean).join('');return'<?xml version="1.0" encoding="UTF-8"?><rss version="2.0" xmlns:media="http://search.yahoo.com/mrss/"><channel><title>NASR MEDIA Social</title><link>'+ORIGIN+'/</link><description>NASR MEDIA social feed</description><language>fa-AF</language><lastBuildDate>'+new Date().toUTCString()+'</lastBuildDate>'+parts+'</channel></rss>'}
