async function deterministicAnalysis(rows:Recent[]){const top=rows.slice(0,3),now=Date.now(),title='مرور تحلیلی نصر مدیا | سه تحول تازه در یک قاب',summary='این مرور تحلیلی سه خبر تازه را کنار هم می‌گذارد تا دامنه هر رویداد و مرز میان واقعیت ثبت‌شده و برداشت تحلیلی روشن بماند. متن فقط بر اطلاعات موجود در همین خبرها تکیه دارد و میان آن‌ها رابطهٔ علّی فرض نمی‌کند.',body=['سه خبر تازه‌ای که هم‌زمان در خروجی نصر مدیا قرار گرفته‌اند، موضوعات متفاوتی را پوشش می‌دهند: '+top.map(x=>'«'+x.title+'»').join('، ')+'. کنار هم قرار دادن این خبرها به معنای مرتبط‌دانستن علت‌ها یا پیامدهای آن‌ها نیست؛ هدف فقط نشان‌دادن دامنه تحولات ثبت‌شده در یک بازه زمانی مشترک است.',...top.map((x,i)=>'در خبر '+['نخست','دوم','سوم'][i]+'، '+x.summary+' این بخش همان اطلاعات منتشرشده در خبر را بازتاب می‌دهد و از افزودن نتیجه‌ای که در منبع وجود ندارد خودداری می‌کند.'),'از مجموعه این گزارش‌ها می‌توان یک نکته روشی گرفت: سرعت تغییر رویدادها ایجاب می‌کند خبر، زمینه و تحلیل از هم جدا بمانند. هرجا داده‌ای درباره علت، پیامد یا ارتباط میان این رویدادها در دسترس نیست، نصر مدیا آن را به‌عنوان واقعیت قطعی بیان نمی‌کند. به همین دلیل این مرور بیش از آن‌که حکم نهایی صادر کند، حدود دانسته‌های فعلی را روشن می‌سازد.'].join('\n\n'),rec:Article={title,summary,body,category:'تحلیل',categoryKey:'analysis',displayTab:'تحلیل',status:'published',confidence:94,created_at:now,updated_at:now,published_at:now,source:'تحریریه نصر مدیا',sourceUrl:'',imageUrl:top[0].imageUrl,imagePath:top[0].imagePath,author:PUBLIC_EDITOR,tags:['nasr-v2-analysis','deterministic-analysis'],views:0,translations:{}};const[id]=await db.add(T_ARTICLES,[rec]);if(!id)throw new Error('analysis_insert_failed');await pushIndex(id);await mirrorRecent(rec,id);return{id,rec}}
async function generateAnalysis(){const rows=(await recentRows()).filter(x=>x.status==='published'&&x.category!=='تحلیل').slice(0,4);if(rows.length<3)return{created:false,reason:'insufficient_recent_news'};const fingerprint=rows.map(x=>x.articleId).join('|'),state=await one<{fingerprint:string;createdAt:number}>('nasr_analysis_state_v2');if(state?.fingerprint===fingerprint||Date.now()-(state?.createdAt||0)<45*60000)return{created:false,reason:'unchanged'};let id='';try{const content=JSON.stringify(rows.map(x=>({title:x.title,summary:x.summary,body:x.body}))),r=await ai.extract({content,prompt:'بر پایه فقط همین خبرهای نصر مدیا یک تحلیل حرفه‌ای، محتاطانه، بی‌طرف و غیرتبلیغاتی به دری بنویس. هیچ واقعیت، عدد، نقل‌قول یا رویداد تازه نساز و هیچ حکومت، گروه یا جریان سیاسی را تبلیغ یا تخریب نکن. میان واقعیت خبر و استنباط تحلیلی مرز روشن بگذار. عنوان دقیق، خلاصه 3 جمله و بدنه 700 تا 1100 واژه در 5 تا 8 پاراگراف باشد. تکرار و شعار ممنوع.',schema:{type:'object',properties:{title:{type:'string'},summary:{type:'string'},body:{type:'string'}},required:['title','summary','body']},temperature:.12,maxRetries:1,maxTokens:5000,thinkingMode:'FAST'}),d=r.data as{title?:string;summary?:string;body?:string};if(!d.title||!d.summary||wordCount(d.body)<600)throw new Error('analysis_quality_rejected');const now=Date.now(),rec:Article={title:stripSource(d.title),summary:stripSource(d.summary),body:stripSource(d.body||''),category:'تحلیل',categoryKey:'analysis',displayTab:'تحلیل',status:'published',confidence:96,created_at:now,updated_at:now,published_at:now,source:'تحریریه نصر مدیا',sourceUrl:'',imageUrl:rows[0].imageUrl,imagePath:rows[0].imagePath,author:PUBLIC_EDITOR,tags:['nasr-v2-analysis'],views:0,translations:{}};id=(await db.add(T_ARTICLES,[rec]))[0]||'';if(!id)throw new Error('analysis_insert_failed');await pushIndex(id);await mirrorRecent(rec,id)}catch(e){console.warn('AI analysis unavailable; no fallback published',e);return{created:false,reason:'analysis_unavailable'}}await upsertOne('nasr_analysis_state_v2',{fingerprint,createdAt:Date.now()});return{created:true,id}}

export async function runArianaEveryFiveMinutes(){const r=await runPipeline(AUTO_BATCH,true);if(!r.published)await repairRecentImages(1).catch(()=>0);return{statusCode:200,body:JSON.stringify(r)}}
export async function runAnalysisHourly(){const dead=(await deadRows()).length;if(dead)await reviveDeadLetters(8,true);if((await queueRows()).length){await runPipeline(RECOVERY_BATCH,true);return{statusCode:200}}const analysis=await generateAnalysis();if(!analysis.created&&(analysis.reason==='unchanged'||analysis.reason==='insufficient_recent_news')){await repairRecentTruncated(1).catch(()=>0);await repairRecentImages(1).catch(()=>0)}return{statusCode:200}}

